:host { display: block; }

.rr-gate {
    max-width: 560px; margin: 16px auto; padding: 24px 24px 20px;
    display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center;
}
.rr-gate-icon { width: 40px; height: 40px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; }
.rr-gate-icon-warn { background: #fef1cd; --slds-c-icon-color-foreground-default: #8c4b02; }
.rr-gate-icon-setup { background: #eef4ff; --slds-c-icon-color-foreground-default: #0b5cab; }
.rr-gate-title { margin: 0; font-size: 16px; font-weight: 700; }
.rr-gate-text { margin: 0; font-size: 13px; color: #444; line-height: 1.45; }
.rr-gate-buttons { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-top: 6px; }

.rr-gate-switch {
    align-self: stretch; margin-top: 8px; padding-top: 12px; border-top: 1px solid #e5e5e5;
    display: flex; flex-direction: column; gap: 8px; text-align: left;
}
.rr-gate-confirm { margin: 0; padding: 8px 12px; border-radius: 4px; background: #fef1cd; color: #5e3600; font-size: 12px; line-height: 1.45; }
.rr-gate-row { display: flex; align-items: flex-end; gap: 8px; }
.rr-gate-days { width: 140px; }
.rr-gate-error { margin: 0; color: #ba0517; font-size: 12px; }

.rr-override {
    display: flex; align-items: center; gap: 8px; padding: 6px 12px; margin-bottom: 8px;
    border-radius: 4px; background: #eef4ff; color: #014486; font-size: 12px;
}
.rr-override-text { margin: 0; flex: 1; }
